//! The frozen cross-implementation corpus battery for the
//! `qtsl_deadline_table` obligation core: every case of
//! `fixtures/deadline_pyref_corpus.json` (generated by the independent
//! python Fractions arm `fixtures/deadline_pyref_gen.py` — different
//! representations, different obligation order, verdicts derived by
//! the python checker) replayed through [`check_deadline`], demanding
//! verdict agreement. The row-decode stratum is exercised by the
//! dispatch battery (`tests/deadline.rs`); this differential pins the
//! WF/B/S/C arithmetic itself.

use num_bigint::{BigInt, BigUint};
use qtsl_geolog_provider::deadline::{check_deadline, DeadlineCert, Face};
use qtsl_geolog_provider::qq::QQ;
use serde_json::Value as J;
use std::collections::HashMap;

fn fr(v: &J) -> QQ {
    let a = v.as_array().expect("fraction pair");
    let num = a[0].as_i64().map(BigInt::from).unwrap_or_else(|| {
        // Large numerators serialize as JSON numbers within i64 for
        // this corpus; anything else is a generator bug.
        panic!("numerator out of i64: {v}")
    });
    let den = a[1].as_u64().map(BigUint::from).expect("denominator u64");
    QQ::new(num, den)
}

#[test]
fn corpus_replays_with_verdict_agreement() {
    let raw = include_str!("fixtures/deadline_pyref_corpus.json");
    let root: J = serde_json::from_str(raw).expect("corpus parses");
    let cases = root["cases"].as_array().expect("cases array");
    assert_eq!(cases.len(), 240, "the frozen corpus is complete");
    let mut holds = 0usize;
    for (i, case) in cases.iter().enumerate() {
        let ns = case["ns"].as_u64().expect("ns") as usize;
        let deadline = case["deadline"].as_u64().expect("deadline") as usize;
        let mut goal = vec![false; ns];
        for g in case["goal"].as_array().expect("goal") {
            goal[g.as_u64().expect("goal idx") as usize] = true;
        }
        let mut absorbing = vec![false; ns];
        for a in case["absorbing"].as_array().expect("absorbing") {
            absorbing[a.as_u64().expect("absorbing idx") as usize] = true;
        }
        let mut kernel: HashMap<(usize, usize), Vec<(usize, QQ)>> = HashMap::new();
        for row in case["kernel"].as_array().expect("kernel") {
            let row = row.as_array().expect("kernel row");
            let s = row[0].as_u64().expect("src") as usize;
            let a = row[1].as_u64().expect("act") as usize;
            let grp = row[2]
                .as_array()
                .expect("group")
                .iter()
                .map(|dp| {
                    let dp = dp.as_array().expect("dest pair");
                    (dp[0].as_u64().expect("dst") as usize, fr(&dp[1]))
                })
                .collect();
            kernel.insert((s, a), grp);
        }
        let mut policy: HashMap<(usize, usize), usize> = HashMap::new();
        for row in case["policy"].as_array().expect("policy") {
            let row = row.as_array().expect("policy row");
            policy.insert(
                (
                    row[0].as_u64().expect("src") as usize,
                    row[1].as_u64().expect("t") as usize,
                ),
                row[2].as_u64().expect("act") as usize,
            );
        }
        let init: Vec<(usize, QQ)> = case["init"]
            .as_array()
            .expect("init")
            .iter()
            .map(|sm| {
                let sm = sm.as_array().expect("init pair");
                (sm[0].as_u64().expect("state") as usize, fr(&sm[1]))
            })
            .collect();
        let claim = fr(&case["claim"]);
        let table: Vec<QQ> = case["table"]
            .as_array()
            .expect("table")
            .iter()
            .map(fr)
            .collect();
        let cert = DeadlineCert {
            face: Face::Ge,
            deadline,
            ns,
            goal,
            absorbing,
            init,
            claim,
            kernel,
            policy,
            table,
        };
        let got = check_deadline(&cert).is_ok();
        let want = case["verdict"].as_bool().expect("verdict");
        assert_eq!(
            got,
            want,
            "case {i}: rust verdict {got:?} against python verdict {want:?} \
             ({:?})",
            check_deadline(&cert)
        );
        if got {
            holds += 1;
        }
    }
    assert_eq!(
        holds,
        root["holds"].as_u64().expect("holds") as usize,
        "hold-count agreement with the generator's summary"
    );
}
